        k = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'D':
                k += 1
            else:
                break
        return k

    def coop_run_end():
        k = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'C':
                k += 1
            else:
                break
        return k

