import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    for a in op:
        if a == 'C':
            opp_c += 1
    opp_d = n - opp_c
    my_c = 0
    for a in me:
        if a == 'C':
            my_c += 1
    my_d = n - my_c

    last_op = op[-1]

    # --- Early game: establish cooperation, punish only genuine betrayal ---
    if n < 4:
        return 'C'

    # --- Payoff-aware self report ---
    my_score = 0
    op_score = 0
    cc = 0
    for i in range(n):
        a = me[i]
        b = op[i]
        if a == 'C':
            if b == 'C':
                my_score += 3
                op_score += 3
                cc += 1
            else:
                op_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                op_score += 1

    # Recent windows
    rlen = min(10, n)
    recent_op = op[-rlen:]
    recent_me = me[-rlen:]
    rec_opp_c = 0
    for a in recent_op:
        if a == 'C':
            rec_opp_c += 1
    rec_opp_d = rlen - rec_opp_c

    # Opponent cooperation rate
    opp_rate = opp_c / n

    # --- Terminal endgame: exploit the last few rounds optimally ---
    rem = 100 - n
    if rem <= 1:
        return 'D'
    if rem <= 3:
        # If opponent is very likely to cooperate, defect to grab 5.
        # If opponent likely defects, defect anyway (avoid 0).
        # Only cooperate if opponent so cooperative that defecting would
        # damage future (no future left) -> always defect except near-pure-C
        # where we still defect (CC=3 vs DC=5, D best against expected C).
        if opp_rate > 0.95 and rec_opp_d == 0:
            # still defect, DC=5 > CC=3
            return 'D'
        return 'D'

    # --- Opponent appears to be near-pure cooperator: exploit aggressively ---
    # Against ALLC, defecting nearly always maximizes cumulative score.
    if n >= 8 and opp_d == 0:
        # No defection observed. Against pure ALLC, D is strictly best.
        # Keep small C occasionally in case of hidden reactivity, but mostly D.
        if rem > 5:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        return 'D'

    if n >= 12 and opp_rate >= 0.95 and rec_opp_d == 0:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # --- Opponent appears to be near-pure defector: defect ---
    if n >= 8 and opp_c == 0:
        return 'D'

    if n >= 10 and opp_rate <= 0.1:
        if rng.random() < 0.02:
            return 'C'
        return 'D'

    # --- Strong reactive detection: opponent copied our last move ---
    # TFT-like opponents will mirror our last action. Against TFT, the
    # optimal is to defect near the end, cooperate otherwise (mutual CC).
    # Against very responsive opponents, avoid initiating DD loops.
    reactive_evidence = 0
    checks = 0
    start = max(1, n - 8)
    for i in range(start, n):
        if op[i] == me[i - 1]:
            reactive_evidence += 1
        checks += 1

    likely_reactive = False
    if checks >= 4 and reactive_evidence >= checks - 1:
        likely_reactive = True

    # --- Detect periodic / patterned defection ---
    # periodic_D: D on first 2 of each 5-cycle.
    # Punish defined patterns but recover to cooperation.
    patterned = False
    if n >= 10:
        matches = 0
        total = 0
        for i in range(n):
            pos = i % 5
            expected = 'D' if pos < 2 else 'C'
            if op[i] == expected:
                matches += 1
            total += 1
        if total > 0 and matches >= total - 1:
            patterned = True

    if patterned:
        # Mirror the pattern: defect when they will defect, cooperate otherwise.
        pos = n % 5
        # But we can gain by defecting on their C positions too if they never punish.
        # Check whether they punish our defections.
        punished = False
        for i in range(1, n):
            if me[i - 1] == 'D' and op[i] == 'D':
                # was it a scheduled D? if not, it's punishment
                if (i % 5) >= 2:
                    punished = True
                    break
        if punished:
            if pos < 2:
                return 'D'
            return 'C'
        else:
            # Exploit freely: they don't punish.
            if pos < 2:
                return 'D'
            if rng.random() < 0.7:
                return 'D'
            return 'C'

    # --- Opponent is currently cooperating recently ---
    if rec_opp_d == 0 and rec_opp_c == rlen and rlen >= 3:
        # Sustained cooperation from opponent.
        # Mutual CC is stable. Only exploit if we have strong evidence
        # opponent won't retaliate.
        # Check: did we ever defect while they were cooperative, and did
        # they punish?
        we_defected_they_stayed_c = 0
        for i in range(n):
            if me[i] == 'D' and op[i] == 'C':
                we_defected_they_stayed_c += 1

        if we_defected_they_stayed_c >= 1:
            # After our D, they still cooperated -> they are forgiving/nonreactive.
            # Lean toward exploitation.
            if rem > 6:
                if rng.random() < 0.6:
                    return 'D'
                return 'C'
            return 'D'

        # No evidence yet -> probe gently to learn reactivity.
        if n >= 20 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # --- Opponent just defected ---
    if last_op == 'D':
        # Count consecutive opponent defections
        run_d = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                run_d += 1
            else:
                break

        # If opponent overall is quite cooperative, forgive isolated defection
        if opp_rate >= 0.75 and run_d == 1:
            # Single isolated D from cooperative opponent -> treat as noise/probe
            # Retaliate once but return quickly (better than endless DD).
            # If we already retaliated last round, return to C.
            if n >= 2 and me[-1] == 'D':
                return 'C'
            return 'D'

        if opp_rate >= 0.5:
            # Moderately cooperative
            if run_d >= 3:
                # Long D run -> punish, but occasionally probe for recovery
                if rec_opp_d >= rlen or (n >= 2 and me[-1] == 'C' and op[-1] == 'D'):
                    pass
                # Try to break DD loops
                if n >= 2 and op[-2] == 'D' and op[-1] == 'D' and me[-1] == 'D':
                    if rng.random() < 0.25:
                        return 'C'
                return 'D'
            if run_d == 2:
                # Two in a row: retaliate harder
                if n >= 2 and op[-2] == 'D' and op[-1] == 'D' and me[-1] == 'D' and me[-2] == 'D':
                    if rng.random() < 0.2:
                        return 'C'
                return 'D'
            # Single defection, moderate opponent
            if me[-1] == 'D':
                return 'C'
            return 'D'

        # Opponent generally defect-heavy: defect back, rare probe
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # --- Opponent just cooperated ---
    # If we defected last and they still cooperated -> strong exploit signal,
    # but be careful of latent punishment.
    if n >= 2 and me[-1] == 'D' and last_op == 'C':
        # They're forgiving. Exploit while keeping occasional C.
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Opponent cooperative, we cooperative, but mixed history
    if opp_rate >= 0.7:
        # Mostly cooperative opponent, currently C.
        # Probe occasionally to detect exploitability.
        if n >= 15 and rem > 5 and rng.random() < 0.06:
            return 'D'
        return 'C'

    if opp_rate >= 0.4:
        # Mixed opponent currently cooperative.
        # Reciprocate cooperation but stay alert.
        if remote_recent_defections(recent_op) >= 3:
            return 'D'
        return 'C'

    # Defect-heavy opponent just cooperated: likely noise or a trap.
    # Probe with caution.
    if rng.random() < 0.5:
        return 'C'
    return 'D'


def remote_recent_defections(recent_op):
    d = 0
    for a in recent_op:
        if a == 'D':
            d += 1
    return d

