def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract opponent moves for quick analysis
    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    last_me, last_opp = history[-1]

    # --- Opening: cooperate, but punish an immediate defection ---
