    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    if n < 3:
        return 'C'

    # Always-defect opponent: defect to minimize losses.
    if op_c == 0:
        return 'D'

