    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_defects += 1
        if m == 'D':
            my_defects += 1
    for i in range(max(0, n - 5), n):
        if history[i][1] == 'D':
            opp_last5_d += 1
    if opp_defects == 0:
        if n >= 90:
