def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

    last_me, last_opp = history[-1]

    defection_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            defection_streak += 1
        else:
            break

    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            coop_streak += 1
        else:
            break

    w = 10 if n >= 10 else n
    recent_opp_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_opp = recent_opp_c / w
    overall_opp = opp_c / n

    remaining = 100 - n
    score_diff = my_score - opp_score

    # Exploit an opponent that has never defected (all-C cooperator).
    if opp_c == n:
        if remaining <= 3:
            return 'D'
        return 'C'

    # Pure retaliation regime: sustained defector.
    if defection_streak >= 4 and recent_opp <= 0.2:
        if rng.random() < 0.05 and remaining > 5:
            return 'C'
        return 'D'

    # If opponent defected last round.
    if last_opp == 'D':
        # Opponent mostly cooperative -> forgive quickly.
        if overall_opp >= 0.7 and defection_streak <= 1:
            return 'C'
        # Long defection streak: punish hard.
        if defection_streak >= 3:
            if rng.random() < 0.08 and remaining > 5:
                return 'C'
            return 'D'
        if defection_streak == 2:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # Isolated defection: retaliate once, then likely forgive.
        if n >= 2 and history[-2][1] == 'C' and overall_opp >= 0.4:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If they have defected a lot overall, defect back sometimes.
    if overall_opp < 0.35:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if overall_opp < 0.55:
        if defection_streak >= 1 and recent_opp < 0.6:
            if rng.random() < 0.3:
                return 'D'
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    # Opponent is generally cooperative; exploit late but not too early.
    if remaining <= 2:
        return 'D'
    if remaining <= 6 and overall_opp >= 0.85:
        return 'D'

    # Long mutual cooperation: rare probing defection.
    if coop_streak >= 12 and remaining > 8:
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    # If we are far behind and opponent looks exploitable, defect.
    if score_diff < -8 and overall_opp >= 0.6:
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    return 'C'

