def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = sum(1 for i in range(n) if opp_at(i) == 'C')
    d_opp = n - c_opp
    coop_rate = c_opp / n

    if d_opp == 0:
        if n >= 90:
            return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    last = opp_at(n - 1)

    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    remaining = 100 - n

    recent_start = n - 12 if n >= 12 else 0
    recent_d = 0
    for j in range(recent_start, n):
        if opp_at(j) == 'D':
            recent_d += 1

    if remaining <= 4:
        if coop_rate >= 0.6 and streak_d == 0:
            return 'D'
        if coop_rate >= 0.85:
            return 'D'
        if coop_rate >= 0.5:
            return 'C'
        return 'D'

    if streak_d >= 3:
        return 'D'

    if streak_d == 2:
        if coop_rate >= 0.7 and recent_d <= 2:
            return 'C'
        return 'D'

    if streak_d == 1:
        if coop_rate >= 0.65:
            if streak_c >= 4:
                return 'C'
            if n >= 3 and opp_at(n - 2) == 'C' and opp_at(n - 3) == 'C':
                return 'C'
            return 'D'
        if coop_rate >= 0.45 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if coop_rate >= 0.85:
        if n >= 85 and rng.random() < 0.3:
            return 'D'
        return 'C'

    if n >= 8:
        mirror = 0
        for j in range(1, n):
            if opp_at(j) == me_at(j - 1):
                mirror += 1
        if mirror >= (n - 1) * 0.75:
            return me_at(n - 1)

    if n >= 6:
        alt = 0
        for j in range(1, n):
            if opp_at(j) != opp_at(j - 1):
                alt += 1
        if alt >= n - 2:
            if last == 'C':
                return 'D'
            return 'C'

    if last == 'C':
        if coop_rate < 0.5 and rng.random() < 0.15:
            return 'D'
        return 'C'

    if coop_rate > 0.55 and streak_d <= 1:
        return 'C'
    if coop_rate > 0.4 and rng.random() < 0.25:
        return 'C'
    return 'D'

