import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = 0
    my_def = 0
    for a in op:
        if a == 'D':
            opp_def += 1
    for a in my:
        if a == 'D':
            my_def += 1

    last_op = op[-1]
    last_my = my[-1]

    # Cooperate against a never-defecting opponent, but probe late.
    if opp_def == 0:
        if n >= 92 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Always defect against a never-cooperating opponent.
    if opp_def == n:
        return 'D'

    # Recent windows
    w = 6
    if n < w:
        w = n
    recent_op = op[-w:]
    recent_def = 0
    for a in recent_op:
        if a == 'D':
            recent_def += 1

    w12 = 12
    if n < w12:
        w12 = n
    recent12 = op[-w12:]
    recent12_def = 0
    for a in recent12:
        if a == 'D':
            recent12_def += 1

    # Consecutive defections at end
    streak = 0
    i = n - 1
    while i >= 0:
        if op[i] == 'D':
            streak += 1
            i -= 1
        else:
            break

    # Consecutive cooperations at end
    coop_streak = 0
    i = n - 1
    while i >= 0:
        if op[i] == 'C':
            coop_streak += 1
            i -= 1
        else:
            break

    # Forgive a single early mistake by returning to cooperation.
    if last_op == 'D':
        if streak == 1 and last_my == 'C' and opp_def <= 3 and n < 40:
            return 'C' if rng.random() < 0.85 else 'D'
        # Long defection streak: punish hard.
        if streak >= 3:
            if streak % 4 == 0:
                return 'C'
            return 'D'
        # Short streak: retaliate but sometimes forgive to avoid spiral.
        if recent12_def >= 8:
            return 'D'
        return 'D' if rng.random() < 0.75 else 'C'

    # Opponent cooperated last round.
    if coop_streak >= 5:
        # Long cooperative run: exploit opportunistically late.
        if n >= 90 and rng.random() < 0.25:
            return 'D'
        if opp_def * 4 < n:
            if rng.random() < 0.08:
                return 'D'
            return 'C'
        return 'C'

    # Moderate defection pressure recently: mix.
    if recent_def >= 3:
        return 'D' if rng.random() < 0.6 else 'C'

    if recent12_def >= 5:
        return 'D' if rng.random() < 0.4 else 'C'

    # Endgame exploitation of mostly-cooperative partners.
    if n >= 88:
        if opp_def * 5 < n and coop_streak >= 2:
            if rng.random() < 0.35:
                return 'D'

    return 'C'

