def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # --- Extract opponent and own actions ---
    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

    # --- Window statistics ---
    def opp_rate(start):
        cnt = 0
        tot = 0
        for i in range(start, n):
            tot += 1
            if opp[i] == 'C':
                cnt += 1
        if tot == 0:
            return 0.5
        return cnt / tot

    w = n if n < 12 else 12
    recent_opp = opp_rate(n - w)
    overall_opp = opp_rate(0)

    # Defection streak of opponent
    d_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            d_streak += 1
        else:
            break

    c_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            c_streak += 1
        else:
            break

    last_me = me[-1]
    last_opp = opp[-1]
    rounds_left = 100 - n

    # --- Early probing: respond to immediate defection, otherwise cooperate ---
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'

    # --- Endgame: last few rounds, try to exploit cooperators ---
    if rounds_left <= 1:
        # Last round: defect if opponent likely cooperates
        if last_opp == 'C' and recent_opp > 0.4:
            return 'D'
        return 'C'

    if rounds_left <= 4:
        if recent_opp >= 0.7:
            # Exploit a cooperating partner at the very end
            return 'D'
        if recent_opp <= 0.3:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # --- Hard punishment of sustained defectors ---
    if d_streak >= 4 and recent_opp <= 0.2:
        # Full defection against relentless defectors
        return 'D'

    if d_streak >= 3 and recent_opp <= 0.3:
        # Mostly defect, rare test
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # --- Forgiveness after isolated defections ---
    if last_opp == 'D':
        # If opponent has been quite cooperative overall, forgive quickly
        if overall_opp >= 0.6 and d_streak <= 2:
            # Forgive, but if repeated defection just occurred, retaliate one more round
            if d_streak == 1 and rng.random() < 0.5:
                return 'C'
            if d_streak == 2 and rng.random() < 0.3:
                return 'C'
            return 'D'
        # Mixed opponent: retaliate but with chance to break loop
        if d_streak >= 3:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        return 'D'

    # --- Opponent cooperated last round ---
    # Exploit very cooperative opponents sparingly
    if c_streak >= 8:
        if rounds_left > 15 and rng.random() < 0.08:
            return 'D'
        return 'C'

    if overall_opp >= 0.75 and recent_opp >= 0.6:
        return 'C'

    # Opponent cooperated but has a troubled history: cautious cooperation
    if recent_opp >= 0.5:
        return 'C'

    # Recent defection trend but last was C: probe
    if recent_opp < 0.35:
        if score_behind(my_score, opp_score) and rng.random() < 0.25:
            return 'D'
        return 'C'

    return 'C'


def score_behind(my_score, opp_score):
    return my_score < opp_score - 4

